        c.addToBalance{value: amount2}();

        // Compute total user balances
        uint256 sumUserBalances = c.getBalance(alice) + c.getBalance(bob);

        // Check invariant: sum of user balances equals contract balance
        assertTrue(sumUserBalances == address(c).balance);
    }
}

