pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address a1, address a2, uint256 val) public {
        vm.assume(a1 != address(0) && a2 != address(0) && a1 != a2);
        vm.deal(a1, val);
        vm.deal(a2, val);

        // Pre-state: compute sum of all user balances (any addresses we may touch)
        uint256 preTotal = c.getBalance(a1) + c.getBalance(a2);

        // Drive the system
        vm.prank(a1);
        (bool ok1, ) = address(c).call{value: val}(abi.encodeWithSignature("addToBalance()"));
        require(ok1, "call1 failed");

        // Post-state: new total
        uint256 postTotal = c.getBalance(a1) + c.getBalance(a2);

        // Rule: total supply increased by exactly msg.value
        assertTrue(postTotal == preTotal + val, "total supply invariant broken");
    }
}

