pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        amount1 = bound(amount1, 0, 1 ether);
        amount2 = bound(amount2, 0, 1 ether);

        vm.deal(address(this), amount1 + amount2);
        uint256 initialContractBalance = address(c).balance;

        // First call to addToBalance
        (bool success1, ) = address(c).call{value: amount1}(abi.encodeWithSignature("addToBalance()"));

        // Second call to addToBalance
        (bool success2, ) = address(c).call{value: amount2}(abi.encodeWithSignature("addToBalance()"));

        // Rule: After two consecutive calls to addToBalance, the contract's ETH balance must equal
        // the total ETH sent (since no withdrawals were made).
        // In the correct version, both calls succeed and the balance increases.
        // In the buggy version, the first call reverts (because require(locked_) fails on fresh contract),
        // so only the second call may succeed or both fail, breaking the invariant.
        assertTrue(
            address(c).balance == initialContractBalance + (success1 ? amount1 : 0) + (success2 ? amount2 : 0)
        );
    }
}

