pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 amount, uint256 withdrawAmount) public {
        vm.assume(sender != address(0));
        vm.assume(amount > 0);
        vm.assume(withdrawAmount <= amount);

        // First call: sender sends ETH to addToBalance
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool success1, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));
        assertTrue(success1, "First addToBalance should succeed");

        // Second call: sender withdraws some balance (or all)
        vm.prank(sender);
        (bool success2, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        // Note: withdrawBalance will always revert if locked_ logic is inverted?
        // Actually, we want to check if after that, addToBalance works.
        // So we ignore success2 (may revert due to insufficient balance in reference?)
        // But in reference, withdrawBalance will succeed only if userBalance[sender] > 0.
        // We need to ensure a scenario where withdrawBalance succeeds.
        // So we restrict: withdrawAmount == amount to clear balance.
        vm.assume(withdrawAmount == amount); // ensures balance goes to zero
        // If withdrawBalance fails, then we skip? No, we want to test the property.
        // Let's just check that after withdrawBalance call (whether it reverts or not), 
        // a subsequent addToBalance succeeds with a new deposit.
        // But the bug makes the first addToBalance revert, so we need a different approach.
        // Actually, the bug is in nonReentrant: require(locked_) makes all calls revert.
        // So the first addToBalance would revert already, but we need a scenario where 
        // reference passes while bug fails.
        // Instead, test: after a successful withdrawBalance, call addToBalance again.

        // Restart: simpler approach: call withdrawBalance first, then addToBalance.
        // But withdrawBalance requires positive balance. So first deposit, then withdraw, then deposit again.
        // This sequence works in reference, but bug causes revert on the second addToBalance? 
        // Actually bug causes all nonReentrant calls to revert, so the first deposit already fails.
        // To distinguish, we need a scenario where reference's first call succeeds but bug's first call fails.
        // The property we test: the first addToBalance after contract deployment succeeds.
        // In reference, it does; in bug, it reverts because locked_ is false at start, and require(locked_) fails.
        // So we can test just a single call: if sent value > 0, call addToBalance and check it returns true.
        // That fits: general rule: any address can call addToBalance with positive value and it will succeed.

        vm.deal(sender, amount);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));
        assertTrue(success, "addToBalance should succeed");
    }
}

